import{_ as a,o as n,c as t,a5 as e}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"24. 字符串作为字符数组","description":"The Little Book of C 中文版 — 24. 字符串作为字符数组","frontmatter":{"title":"24. 字符串作为字符数组","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","03-内存","中文"],"description":"The Little Book of C 中文版 — 24. 字符串作为字符数组","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":24,"sidebarWeight":24,"alternateZh":"/posts/c教程/zh-CN/03-内存/024-Strings as Character Arrays","alternateEn":"/posts/c教程/en-US/03-Working with Memory/024-Strings as Character Arrays"},"headers":[],"relativePath":"posts/c教程/zh-CN/03-内存/024-Strings as Character Arrays.md","filePath":"posts/c教程/zh-CN/03-内存/024-Strings as Character Arrays.md","lastUpdated":1790163617000}'),p={name:"posts/c教程/zh-CN/03-内存/024-Strings as Character Arrays.md"};function i(o,s,l,c,d,r){return n(),t("div",null,[...s[0]||(s[0]=[e(`<p>[English version](/posts/c教程/en-US/03-Working with Memory/024-Strings as Character Arrays)</p><p>在 C 中，字符串只是一个以特殊空字符结尾的字符数组<code>&#39;\\0&#39;</code>。与高级语言不同，C 没有内置的字符串类型，只有数组和指针。这种简单性使您可以完全控制文本数据，但也需要小心：每个字符串操作都必须遵守内存限制和空终止符。</p><h4 id="弦乐的工作原理" tabindex="-1">弦乐的工作原理 <a class="header-anchor" href="#弦乐的工作原理" aria-label="Permalink to &quot;弦乐的工作原理&quot;">​</a></h4><p>像这样的字符串<code>&quot;Hello&quot;</code>在C中内部表示为：</p><table tabindex="0"><thead><tr><th>人物</th><th>哈</th><th>电子</th><th>我</th><th>我</th><th>哦</th><th><code>\\0</code></th></tr></thead><tbody><tr><td>索引</td><td>0</td><td>1</td><td>2</td><td>3</td><td>4</td><td>5</td></tr></tbody></table><p>这<code>&#39;\\0&#39;</code>(ASCII 0) 标记字符串的结尾，这就是函数的方式<code>printf</code>或者<code>strlen</code>知道在哪里停下来。</p><h4 id="声明字符串" tabindex="-1">声明字符串 <a class="header-anchor" href="#声明字符串" aria-label="Permalink to &quot;声明字符串&quot;">​</a></h4><p>声明字符串有两种常见方法：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>char greeting1[] = &quot;Hello&quot;;        // automatic null terminator</span></span>
<span class="line"><span>char greeting2[6] = {&#39;H&#39;,&#39;e&#39;,&#39;l&#39;,&#39;l&#39;,&#39;o&#39;,&#39;\\0&#39;}; // explicit</span></span>
<span class="line"><span>char *greeting3 = &quot;Hello&quot;;         // pointer to string literal</span></span></code></pre></div><p><code>greeting1</code>是一个可以修改的可变数组。<code>greeting3</code>指向存储在内存中的只读字符串文字，修改它会导致未定义的行为。</p><h4 id="小代码" tabindex="-1">小代码 <a class="header-anchor" href="#小代码" aria-label="Permalink to &quot;小代码&quot;">​</a></h4><p>这是一个完整的示例，探讨了字符串声明、迭代和基本操作：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    char msg[] = &quot;C language&quot;;</span></span>
<span class="line"><span>    char *ptr = msg; // pointer to the first character</span></span>
<span class="line"><span>    printf(&quot;String: %s\\n&quot;, msg);</span></span>
<span class="line"><span>    printf(&quot;Length: %zu\\n&quot;, strlen(msg));</span></span>
<span class="line"><span>    printf(&quot;\\nCharacters one by one:\\n&quot;);</span></span>
<span class="line"><span>    for (int i = 0; msg[i] != &#39;\\0&#39;; i++) {</span></span>
<span class="line"><span>        printf(&quot;msg[%d] = %c (address: %p)\\n&quot;, i, msg[i], (void *)&amp;msg[i]);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    printf(&quot;\\nAccess via pointer arithmetic:\\n&quot;);</span></span>
<span class="line"><span>    for (int i = 0; *(ptr + i) != &#39;\\0&#39;; i++) {</span></span>
<span class="line"><span>        printf(&quot;*(ptr + %d) = %c\\n&quot;, i, *(ptr + i));</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    // Modify string safely</span></span>
<span class="line"><span>    msg[0] = &#39;C&#39;;</span></span>
<span class="line"><span>    msg[1] = &#39;+&#39;;</span></span>
<span class="line"><span>    printf(&quot;\\nModified string: %s\\n&quot;, msg);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译并运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc strings_demo.c -o strings_demo</span></span>
<span class="line"><span>./strings_demo</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>字符串：C语言</span></span>
<span class="line"><span>长度：10</span></span>
<span class="line"><span></span></span>
<span class="line"><span>人物一一：</span></span>
<span class="line"><span>消息[0] = C（地址：0x7ffd29c4a0a0）</span></span>
<span class="line"><span>消息[1] =（地址：0x7ffd29c4a0a1）</span></span>
<span class="line"><span>msg[2] = l（地址：0x7ffd29c4a0a2）</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>通过指针运算访问：</span></span>
<span class="line"><span>*(ptr + 0) = C</span></span>
<span class="line"><span>*（指针+ 1）=  </span></span>
<span class="line"><span>*(ptr + 2) = l</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>修改字符串：C+anguage</span></span></code></pre></div><h4 id="常见的字符串操作" tabindex="-1">常见的字符串操作 <a class="header-anchor" href="#常见的字符串操作" aria-label="Permalink to &quot;常见的字符串操作&quot;">​</a></h4><p>C提供了几个标准函数<code>&lt;string.h&gt;</code>:</p><table tabindex="0"><thead><tr><th>功能</th><th>描述</th><th>示例</th></tr></thead><tbody><tr><td><code>strlen(s)</code></td><td>获取字符串长度（不包括<code>\\0</code>)</td><td><code>strlen(&quot;Hi&quot;) == 2</code></td></tr><tr><td><code>strcpy(dest, src)</code></td><td>复制字符串</td><td><code>strcpy(name, &quot;Bob&quot;);</code></td></tr><tr><td><code>strcat(dest, src)</code></td><td>连接字符串</td><td><code>strcat(full, last);</code></td></tr><tr><td><code>strcmp(a, b)</code></td><td>比较字符串 (<code>0</code>如果相等）</td><td><code>strcmp(&quot;a&quot;,&quot;b&quot;)</code></td></tr><tr><td><code>strchr(s, c)</code></td><td>查找第一个出现的字符</td><td><code>strchr(word, &#39;a&#39;)</code></td></tr><tr><td><code>strstr(s, sub)</code></td><td>查找子串</td><td><code>strstr(text, &quot;find&quot;)</code></td></tr></tbody></table><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>char a[20] = &quot;Hello, &quot;;</span></span>
<span class="line"><span>char b[] = &quot;World!&quot;;</span></span>
<span class="line"><span>strcat(a, b);</span></span>
<span class="line"><span>printf(&quot;%s\\n&quot;, a); // &quot;Hello, World!&quot;</span></span></code></pre></div><h4 id="指针和字符串" tabindex="-1">指针和字符串 <a class="header-anchor" href="#指针和字符串" aria-label="Permalink to &quot;指针和字符串&quot;">​</a></h4><p>因为字符串的名称会衰减为指针，所以您可以将字符串直接传递给函数：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void greet(const char *name) {</span></span>
<span class="line"><span>    printf(&quot;Hello, %s!\\n&quot;, name);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    greet(&quot;C Learner&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>const char *</code>防止意外修改字符串文字。</p><h4 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h4><p>遗忘<code>&#39;\\0&#39;</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>char word[4] = {&#39;T&#39;,&#39;e&#39;,&#39;s&#39;,&#39;t&#39;}; // missing terminator, unsafe</span></span></code></pre></div><p>缓冲区溢出：复制的字符数量超出目标缓冲区的容纳范围会导致未定义的行为。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>char dest[5];</span></span>
<span class="line"><span>strcpy(dest, &quot;Too long!&quot;); // dangerous</span></span></code></pre></div><p>修改字符串文字：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>char *s = &quot;Hello&quot;;</span></span>
<span class="line"><span>s[0] = &#39;Y&#39;; // crash or undefined behavior</span></span></code></pre></div><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>字符串是 C 语言中文本处理、文件处理和用户界面的基础。因为它们只是字符数组，所以理解字符串迫使您思考：</p><ul><li>内存布局</li><li>空终止</li><li>缓冲区大小和安全性</li></ul><p>一旦您内部化了 C 如何在字节级别处理文本，您就可以构建真正的解析器、文件读取器和命令行工具。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>编写一个函数<code>void reverse(char *s)</code>就地反转字符串。</li><li>实现您自己的版本<code>strlen</code>.</li><li>创建一个计算字符串中元音的程序。</li><li>使用连接两个用户输入的字符串<code>strcat</code>.</li><li>尝试打印一个不带字符串的字符串<code>&#39;\\0&#39;</code>，观察会发生什么。</li></ol><p>C 中的字符串既优雅又危险，这是对精度的真正考验。一旦掌握了它们，您就会了解文本如何真正存在于内存中，一次一个字节。</p>`,40)])])}const g=a(p,[["render",i]]);export{u as __pageData,g as default};
